import{_ as o,o as s,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.2.4 Reset Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-4-reset-password/spec.md","filePath":"feature/authentication/3-2-4-reset-password/spec.md"}'),r={name:"feature/authentication/3-2-4-reset-password/spec.md"};function d(i,e,n,c,l,h){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-2-4-reset-password" tabindex="-1">3.2.4 Reset Password <a class="header-anchor" href="#_3-2-4-reset-password" aria-label="Permalink to &quot;3.2.4 Reset Password&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.4</td></tr><tr><td>Feature</td><td>Reset Password (forgot-password request + reset-password with token)</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any USER who cannot sign in because the password is forgotten (unauthenticated)</td></tr><tr><td>Version</td><td>1.1 — 2026-09-25 — corrected BR-12 mechanism (issuedAt vs lastPasswordChange, not jti blacklist)</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><p>Note: this FR is the forgot/reset flow only. Changing a known password while logged in is FR 3.2.5 Change Password (<code>POST /api/v1/auth/change-password</code>), a separate FR.</p><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a user who has forgotten the password opens <code>/forgot-password</code> and submits an email address.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Unauthenticated USER who cannot sign in because the password is forgotten.</li><li><strong>Purpose:</strong> Restore access to the account by email through a single-use reset link, without ever revealing whether a given email is registered, and force sign-in again on every device once the password is changed.</li><li><strong>Interface:</strong> <code>/forgot-password</code> (email input, <code>ForgotPasswordPage.tsx</code>) and <code>/reset-password?token=...</code> (new password + confirm password, <code>ResetPasswordPage.tsx</code>).</li><li><strong>Data Processing:</strong> <code>POST /api/v1/auth/forgot-password</code> always returns 200 regardless of whether the email exists; if it exists, the system invalidates any earlier reset token for that account, generates a new single-use token, and emails it. <code>POST /api/v1/auth/reset-password</code> consumes the token atomically, hashes the new password, updates <code>lastPasswordChange</code>, and writes an audit log entry.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Forgot Password / Reset Password screens (<code>brandhub-web-dashboard/src/pages/auth/ForgotPasswordPage.tsx</code>, <code>ResetPasswordPage.tsx</code>):</p><ul><li><code>/forgot-password</code>: brand panel + email <code>Input</code> (required) and an &quot;orange&quot; submit <code>Button</code>. On success the form is replaced by a confirmation panel (check-circle icon, heading, <code>successMessage</code> text interpolating the submitted email) with a &quot;back to login&quot; button — the UI does not say whether the email was actually found, matching BR-13.</li><li><code>/reset-password</code>: reads <code>token</code> from the URL query string; if absent, redirects to <code>/forgot-password</code> immediately (<code>useEffect</code> guard). Shows <code>PasswordInput</code> for the new password with a live <code>PasswordStrengthMeter</code>, a second <code>PasswordInput</code> for confirmation, and a submit button. Client-side validation before submit: new password required, length ≥ 8, at least one digit, and must equal the confirmation — mirroring BR-02/MSG05 and MSG06.</li><li>Both screens share <code>AuthBrandPanel</code>, <code>AuthMobileHeader</code>, and a <code>BackToHomeLink</code>/&quot;back to login&quot; link.</li><li>Toasts: MSG15 on forgot-password success (always shown, whether or not the email exists), MSG16/MSG17 on reset-password failure (invalid/expired vs. already-used token, surfaced via <code>extractErrorMessage</code> from the API error code), MSG18 on reset-password success, after which the user is redirected to <code>/login</code>.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>email</code> (forgot-password step, <code>ForgotPasswordRequest</code>); <code>token</code>, <code>newPassword</code> (reset step, <code>ResetPasswordRequest</code>).</li><li><strong>Input optional:</strong> <code>confirmPassword</code> — validated on the client only (<code>ResetPasswordPage.tsx</code>), never sent to the API.</li><li><strong>System data:</strong> <code>User.id</code>, <code>User.email</code>, <code>User.passwordHash</code>, <code>User.lastPasswordChange</code>; Redis key <code>pwd:reset:{token}</code> → userId (TTL = <code>appProperties.passwordResetTtlSeconds</code>, default 3600s); reverse-index key <code>pwd:reset:user:{userId}</code> → the currently valid token (same TTL).</li><li><strong>Output:</strong> <code>ApiResponse&lt;Void&gt;</code>, 200, no payload, for both endpoints — the response body never distinguishes success/failure cases that must stay silent (BR-13).</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-13:</strong> <code>POST /forgot-password</code> always returns 200 OK whether or not the email exists (<code>AuthServiceImpl.forgotPassword</code>: if <code>userRepository.findByEmail</code> finds nothing, the method returns silently — no error, no email — still 200). When the email exists: any existing token for that user (read via the <code>pwd:reset:user:{userId}</code> reverse-index) is deleted first, then a new 32-byte <code>SecureRandom</code> hex token is generated and stored at <code>pwd:reset:{token}</code> → userId with TTL = <code>appProperties.getPasswordResetTtlSeconds()</code> (≤ 1h per BR), and the reverse-index is refreshed with the same TTL. Only the most recently issued token is ever valid — an earlier link is invalidated the instant a new one is requested. <code>resetPassword</code> reads <code>pwd:reset:{token}</code>; missing/expired/superseded → 400 <code>RESET_TOKEN_INVALID</code>. The key is then deleted atomically (<code>redis.delete</code> returning a boolean); if the delete reports the key was already gone (concurrent reuse) → 400 <code>RESET_TOKEN_USED</code>. If the token decodes to a user id that no longer exists → 400 <code>RESET_TOKEN_INVALID</code>.</li><li><strong>BR-02 (password policy, referenced):</strong> the new password must satisfy the platform password policy (min 8 characters + at least 1 digit, enforced client-side in <code>ResetPasswordPage.tsx</code>&#39;s <code>validate()</code>; server-side, malformed/empty <code>newPassword</code> fails bean validation on <code>ResetPasswordRequest</code> → 400 <code>VALIDATION_ERROR</code>). The accepted password is stored as a BCrypt hash.</li><li><strong>BR-12 (side effect, cross-FR):</strong> after a successful reset, every refresh token issued before the change is rejected on its next use, forcing sign-in again on every device. This is enforced in <code>AuthServiceImpl.refresh()</code>, not in <code>resetPassword</code> itself: <code>refresh()</code> compares the refresh token&#39;s <code>issuedAt</code> claim against <code>user.getLastPasswordChange()</code> and throws <code>REFRESH_TOKEN_INVALID</code> (401) when the token predates the change. <code>resetPassword</code> only sets <code>lastPasswordChange = now</code>; it does not touch any token blacklist. (The separate jti-blacklist check inside <code>refresh()</code> exists for tokens already consumed by <code>logout</code>/a prior <code>refresh</code> call — a different mechanism, not password-reset invalidation.)</li><li><code>resetPassword</code> also deletes the <code>pwd:reset:user:{userId}</code> reverse-index once the token is consumed, and writes an <code>AuditLog</code> row with <code>action = PASSWORD_RESET</code>.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>email</code> empty/blank on <code>/forgot-password</code> → client blocks submit, Display: MSG02.</li><li><code>email</code> not a valid format → bean validation on <code>ForgotPasswordRequest</code> → 400 <code>VALIDATION_ERROR</code>, Display: MSG04.</li><li><code>newPassword</code> missing, under 8 characters, or missing a digit on <code>/reset-password</code> → client blocks submit, Display: MSG05; if it reaches the server anyway → 400 <code>VALIDATION_ERROR</code>.</li><li><code>confirmPassword</code> ≠ <code>newPassword</code> → client blocks submit, Display: MSG06 (never sent to the API).</li><li><code>token</code> missing from the URL → client redirects to <code>/forgot-password</code> before rendering the form (no server call).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>User opens <code>/forgot-password</code> and submits the email address.</li><li><code>AuthController.forgotPassword</code> calls <code>AuthServiceImpl.forgotPassword(email)</code>. The system looks up the account by normalized (lowercased, trimmed) email.</li><li>If found: the system deletes any earlier reset token for the account, generates a new 32-byte random hex token, stores it in Redis with TTL ≤ 1h, refreshes the reverse-index, and sends the reset email via <code>MailService.sendPasswordResetEmail</code>.</li><li>The endpoint returns 200 with no body regardless of whether the account was found. Toast MSG15 (&quot;If the email is registered, a password reset link has been sent to {email_address}.&quot;).</li><li>User opens the reset link from the email, landing on <code>/reset-password?token=...</code>; enters the new password and confirmation (validated on the client).</li><li><code>AuthController.resetPassword</code> calls <code>AuthServiceImpl.resetPassword(token, newPassword)</code>. The system resolves and atomically deletes the Redis token, loads the user, clears the reverse-index, hashes and saves the new password, sets <code>lastPasswordChange = now</code>, and writes an audit log entry.</li><li>The endpoint returns 200 with no body. Toast MSG18 (&quot;Password updated successfully.&quot;); the user is redirected to <code>/login</code>.</li><li>Side effect (BR-12): the next time any refresh token issued before this reset is presented to <code>POST /refresh</code>, it is rejected with 401 <code>REFRESH_TOKEN_INVALID</code>, forcing sign-in again on that device.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>1.a1: <code>email</code> empty → Display: MSG02 (client-blocked, no request sent). 1.a2: The user fills in the field and resubmits.</li><li>1.b1: <code>email</code> not a valid format → 400 <code>VALIDATION_ERROR</code>, Display: MSG04. 1.b2: The user corrects the format and resubmits.</li><li>2.a1: Email does not match any account (BR-13) → still 200, toast MSG15, no email sent. 2.a2: The user checks the inbox; the response never confirms whether the account exists.</li><li>6.a1: Token missing, expired, or superseded by a newer forgot-password request (BR-13) → 400 <code>RESET_TOKEN_INVALID</code>, toast MSG16. 6.a2: The user requests a new reset link from <code>/forgot-password</code>.</li><li>6.b1: Token already consumed, including two near-simultaneous reset submissions racing on the same token (BR-13) → 400 <code>RESET_TOKEN_USED</code>, toast MSG17. 6.b2: The user requests a new reset link.</li><li>6.c1: Token decodes to a user id that no longer exists (deleted account) → 400 <code>RESET_TOKEN_INVALID</code>, toast MSG16. 6.c2: The user requests a new reset link.</li><li>6.d1: <code>newPassword</code> fails the password policy (BR-02) → client-blocked, Display: MSG05; if bypassed, server returns 400 <code>VALIDATION_ERROR</code>. 6.d2: The user corrects the password and resubmits.</li><li>6.e1: <code>confirmPassword</code> mismatch on the client → Display: MSG06, submit blocked (no API call). 6.e2: The user re-types the confirmation.</li><li>No <code>token</code> in the URL when opening <code>/reset-password</code> → the client redirects to <code>/forgot-password</code> before any form is shown.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>On a successful reset: <code>User.passwordHash</code> is replaced and <code>User.lastPasswordChange</code> is set to the reset time; an <code>AuditLog</code> row (<code>PASSWORD_RESET</code>) exists; the consumed Redis token and its reverse-index entry are both deleted.</li><li>On any <code>/forgot-password</code> call: exactly one valid reset token exists per account at a time (the newest one); the HTTP response is 200 in every case and never reveals account existence.</li><li>Refresh tokens issued before the reset are rejected on their next use (BR-12), independent of any explicit logout.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Changing a known password while authenticated — FR 3.2.5 Change Password (<code>POST /api/v1/auth/change-password</code>, <code>ChangePasswordRequest</code>), a separate FR and separate error/message set (<code>WRONG_CURRENT_PASSWORD</code>, <code>SAME_AS_CURRENT_PASSWORD</code>).</li><li>OTP-based reset — the codebase&#39;s OTP flow (<code>otp:*</code> Redis keys, <code>verify-otp</code>/<code>resend-otp</code>) is used for email verification at registration, not for password reset; reset uses a link/token only.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/Section5_Requirement_Appendix.html">Section5_Requirement_Appendix.md</a> (BR-13, BR-12, BR-02; MSG02, MSG04, MSG05, MSG06, MSG15–MSG18)</p>',28)])])}const w=o(r,[["render",d]]);export{p as __pageData,w as default};
